// Edit this list to add or remove sources. No other node needs changing.
// Every URL was verified on 25 Aug 2026 to return a live feed to a
// SERVER-SIDE client (which is what n8n is).
//
// Deliberately NOT included - these block server-side fetches and would fail
// silently inside n8n:
//   The Irrawaddy    https://www.irrawaddy.com/feed          403 Cloudflare
//   Frontier Myanmar https://www.frontiermyanmar.net/en/feed/ 403 Cloudflare
//   Mizzima          https://mizzima.com/feed                 403 Cloudflare
//   ReliefWeb RSS    https://reliefweb.int/country/mmr/rss.xml 406 bot block
//   ReliefWeb API    api.reliefweb.int/v2                      403, needs a
//                    registered appname - apply at reliefweb.int/help/api
const feeds = [
  { source: 'Myanmar Now',    feedUrl: 'https://myanmar-now.org/en/feed/' },
  { source: 'Myanmar Now (Burmese)', feedUrl: 'https://myanmar-now.org/mm/feed/' },
  { source: 'DVB',            feedUrl: 'https://english.dvb.no/feed' },
  { source: 'RFA (Burmese)',  feedUrl: 'https://www.rfa.org/burmese/rss2.xml' },
  { source: 'BNI Online',     feedUrl: 'https://www.bnionline.net/en/rss.xml' }
];

return feeds.map((feed) => ({ json: feed }));

// Map feed items onto the exact contract POST /api/posts enforces, and drop
// anything not relevant. Length caps mirror app/api/posts/route.ts so the
// website never rejects an item for being too long.

const MAX_AGE_DAYS = 3;
const MAX_PER_RUN = 25;

// Attribution is derived from the article's own hostname. Do NOT read it from
// the Feed list node: the RSS node fans one feed out into many items, so item
// pairing is unreliable and every item would inherit the first feed's name.
//
// `keywordFilter` matters. Every outlet below is Myanmar-dedicated, so their
// items are in scope by definition. Applying an English keyword filter to
// them would silently discard every Burmese-language article, since Burmese
// copy never contains the string "Myanmar". Only set keywordFilter: true for
// a general or global feed where filtering is genuinely needed.
const SOURCES = [
  { match: /myanmar-now\.org$/i, source: 'Myanmar Now', category: 'News',        keywordFilter: false },
  { match: /dvb\.no$/i,          source: 'DVB',         category: 'News',        keywordFilter: false },
  { match: /rfa\.org$/i,         source: 'RFA',         category: 'News',        keywordFilter: false },
  { match: /bnionline\.net$/i,   source: 'BNI Online',  category: 'News',        keywordFilter: false },
  { match: /reliefweb\.int$/i,   source: 'ReliefWeb',   category: 'Humanitarian', keywordFilter: false }
];

// Only applied to sources with keywordFilter: true.
const MUST_MATCH = /myanmar|burma|burmese|rohingya|rakhine|kachin|karen|karenni|chin state|shan|sagaing|magway|yangon|mandalay|naypyidaw|junta|tatmadaw|coup/i;

const strip = (html) => String(html || '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ')
  .trim();

const clamp = (value, max) => {
  const text = strip(value);
  if (text.length <= max) return text;
  return text.slice(0, max - 1).replace(/\s+\S*$/, '') + '…';
};

const cutoff = Date.now() - MAX_AGE_DAYS * 24 * 60 * 60 * 1000;
const out = [];
const seen = new Set();

for (const item of $input.all()) {
  const rss = item.json;

  const title = clamp(rss.title, 140);
  const link = String(rss.link || rss.guid || '').trim();
  if (!title || !/^https?:\/\//i.test(link)) continue;
  if (seen.has(link)) continue;

  let host = '';
  try { host = new URL(link).hostname.replace(/^www\./i, ''); } catch { continue; }
  const known = SOURCES.find((entry) => entry.match.test(host));
  const source = known ? known.source : host;
  const category = known ? known.category : 'News';

  const published = Date.parse(rss.isoDate || rss.pubDate || '') || 0;
  if (published && published < cutoff) continue;

  const summary = clamp(rss.contentSnippet || rss.content || rss.description, 380);

  if ((!known || known.keywordFilter) && !MUST_MATCH.test(title + ' ' + summary)) continue;

  seen.add(link);

  // We summarise and link with attribution. We do not republish full articles.
  out.push({
    json: {
      dedupeKey: link,
      title,
      excerpt: clamp(summary + ' (Source: ' + source + ')', 420),
      body: clamp(
        summary +
        '\n\nSource: ' + source +
        '\nRead the original: ' + link +
        '\n\nIngested automatically as a draft. Review, verify and edit before publishing.',
        20000
      ),
      category: clamp(category, 40),
      placement: 'stories',
      status: 'draft',
      channels: ['Website'],
      author: source + ' (via automated ingest)',
      sourceUrl: link,
      publishedAt: published ? new Date(published).toISOString() : null
    }
  });
}

out.sort((a, b) => String(b.json.publishedAt || '').localeCompare(String(a.json.publishedAt || '')));
return out.slice(0, MAX_PER_RUN);

// Cross-run dedupe using workflow static data, so an article is never
// drafted twice. Deliberately NOT the Remove Duplicates node: its
// "items seen in previous executions" mode needs a recent n8n and imports
// as a broken node on older instances. This works on every version.

const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.seenLinks)) store.seenLinks = [];

const seen = new Set(store.seenLinks);
const fresh = [];

for (const item of $input.all()) {
  const key = item.json.dedupeKey;
  if (!key || seen.has(key)) continue;
  seen.add(key);
  fresh.push(item);
}

// Keep the memory bounded; 2000 links is roughly a month at this volume.
store.seenLinks = Array.from(seen).slice(-2000);

return fresh;
